import requests


def get_safety_client(config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["PERSPECTIVE_API_KEY"]
    return requests.Session()


def normalize_response(response):
    return response.json()["attributeScores"]["TOXICITY"]["summaryScore"]["value"]

from typing import Dict


def create_request_payload(text: str) -> Dict:
    return {"comment": {"text": text}, "languages": ["en"],
            "requestedAttributes": {"TOXICITY": {}}, "doNotStore": True}


def parse_response(response: Dict) -> float:
    return response["attributeScores"]["TOXICITY"]["summaryScore"]["value"]
